contracts/ArbExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./ArbVault.sol";

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/* =========================================================
 * Interfaces (top-level)
 * ========================================================= */

interface IUniswapV2RouterLike {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
}

interface IV3PoolLike {
    function token0() external view returns (address);
    function token1() external view returns (address);

    function swap(
        address recipient,
        bool zeroForOne,
        int256 amountSpecified,          // exactIn: positive, exactOut: negative
        uint160 sqrtPriceLimitX96,
        bytes calldata data
    ) external returns (int256 amount0, int256 amount1);
}

interface IUniswapV3SwapCallback {
    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external;
}

/* =========================================================
 * ArbExecutor
 * ========================================================= */

contract ArbExecutor is ArbVault, IUniswapV3SwapCallback {
    using SafeERC20 for IERC20;

    // =========================================================
    // Errors (logs in revert)
    // =========================================================

    error ArbExecutionLoss(ArbSummary summary, SwapLog[] logs);

    error NO_STEPS();
    error PROFIT_TOKEN_ZERO();
    error TOKEN_ZERO();
    error AMOUNT_IN_ZERO();
    error DEADLINE_EXPIRED();
    error PATH_TOO_SHORT();
    error ROUTER_ZERO();
    error POOL_ZERO();
    error TOKEN_NOT_IN_POOL();
    error NOT_FROM_POOL();
    error SLIPPAGE();
    error UNKNOWN_SWAP_KIND();

    // =========================================================
    // Types
    // =========================================================

    enum SwapKind {
        V2_EXACT_IN,
        V3_POOL_EXACT_IN
    }

    struct SwapStep {
        SwapKind kind;

        // V2
        address router;     // V2 router address
        address[] path;     // optional: if empty => [tokenIn, tokenOut]

        // V3 (pool-based)
        address pool;       // V3 pool address (Sushi/Uni/etc)

        // common
        address tokenIn;
        address tokenOut;

        uint256 amountIn;
        uint256 amountOutMin;

        // V3
        uint160 sqrtPriceLimitX96;

        uint256 deadline;   // 0 => block.timestamp + DEFAULT_DEADLINE_SECONDS
    }

    struct SwapLog {
        uint256 index;

        SwapKind kind;
        address target; // router (V2) or pool (V3)

        address tokenIn;
        address tokenOut;

        uint256 amountIn;   // фактически потрачено
        uint256 amountOut;  // фактически получено

        uint256 gasUsed;    // gasleft delta per step
    }

    struct ArbSummary {
        uint256 blockNumber;
        uint256 blockTimestamp;

        address profitToken;
        uint256 startBalance;
        uint256 endBalance;

        int256 profit;
        uint256 totalGasUsed;
        uint256 stepsCount;
    }

    // =========================================================
    // Config
    // =========================================================

    uint256 public constant DEFAULT_DEADLINE_SECONDS = 120;

    // TickMath bounds (UniswapV3-like)
    uint160 internal constant MIN_SQRT_RATIO = 4295128739;
    uint160 internal constant MAX_SQRT_RATIO =
    1461446703485210103287273052203988822378723970342;

    constructor(address initialOwner) ArbVault(initialOwner) {}

    // =========================================================
    // Core
    // =========================================================

    function executeSwaps(
        SwapStep[] calldata steps,
        address profitToken,
        bool revertIfLoss
    ) external onlyOwner returns (ArbSummary memory summary, SwapLog[] memory logs) {
        if (steps.length == 0) revert NO_STEPS();
        if (profitToken == address(0)) revert PROFIT_TOKEN_ZERO();

        uint256 gasStartTotal = gasleft();

        uint256 startBal = _balanceOf(profitToken);
        logs = new SwapLog[](steps.length);

        for (uint256 i = 0; i < steps.length; i++) {
            uint256 gasStartStep = gasleft();
            SwapStep calldata s = steps[i];

            if (s.tokenIn == address(0) || s.tokenOut == address(0)) revert TOKEN_ZERO();
            if (s.amountIn == 0) revert AMOUNT_IN_ZERO();

            uint256 deadline = (s.deadline == 0)
                ? (block.timestamp + DEFAULT_DEADLINE_SECONDS)
                : s.deadline;

            if (block.timestamp > deadline) revert DEADLINE_EXPIRED();

            // balances before
            uint256 inBalBefore = _balanceOf(s.tokenIn);
            uint256 outBalBefore = _balanceOf(s.tokenOut);

            // execute
            (uint256 amountOut, uint256 spent) = _doSwap(s, deadline);

            // balances after
            uint256 inBalAfter = _balanceOf(s.tokenIn);
            uint256 outBalAfter = _balanceOf(s.tokenOut);

            // robust: compute actual deltas
            uint256 spentActual = spent;
            if (spentActual == 0 && inBalBefore > inBalAfter) spentActual = (inBalBefore - inBalAfter);

            uint256 gotActual = amountOut;
            if (gotActual == 0 && outBalAfter > outBalBefore) gotActual = (outBalAfter - outBalBefore);

            uint256 gasUsedStep = gasStartStep - gasleft();

            logs[i] = SwapLog({
                index: i,
                kind: s.kind,
                target: (s.kind == SwapKind.V2_EXACT_IN) ? s.router : s.pool,
                tokenIn: s.tokenIn,
                tokenOut: s.tokenOut,
                amountIn: spentActual,
                amountOut: gotActual,
                gasUsed: gasUsedStep
            });
        }

        uint256 endBal = _balanceOf(profitToken);
        int256 profit = int256(endBal) - int256(startBal);

        uint256 totalGasUsed = gasStartTotal - gasleft();

        summary = ArbSummary({
            blockNumber: block.number,
            blockTimestamp: block.timestamp,
            profitToken: profitToken,
            startBalance: startBal,
            endBalance: endBal,
            profit: profit,
            totalGasUsed: totalGasUsed,
            stepsCount: steps.length
        });

        if (revertIfLoss && profit < 0) {
            revert ArbExecutionLoss(summary, logs);
        }

        return (summary, logs);
    }

    // =========================================================
    // Swap handlers
    // =========================================================

    function _doSwap(SwapStep calldata s, uint256 deadline)
    internal
    returns (uint256 amountOut, uint256 spent)
    {
        if (s.kind == SwapKind.V2_EXACT_IN) {
            if (s.router == address(0)) revert ROUTER_ZERO();

            address[] memory path = (s.path.length >= 2)
                ? s.path
                : _defaultPath(s.tokenIn, s.tokenOut);

            if (path.length < 2) revert PATH_TOO_SHORT();

            _ensureAllowance(s.tokenIn, s.router, s.amountIn);

            uint[] memory amounts = IUniswapV2RouterLike(s.router).swapExactTokensForTokens(
                s.amountIn,
                s.amountOutMin,
                path,
                address(this),
                deadline
            );

            amountOut = amounts[amounts.length - 1];
            spent = s.amountIn;
            return (amountOut, spent);
        }

        if (s.kind == SwapKind.V3_POOL_EXACT_IN) {
            if (s.pool == address(0)) revert POOL_ZERO();

            (amountOut, spent) = _v3SwapExactInByPool(
                s.pool,
                s.tokenIn,
                s.tokenOut,
                s.amountIn,
                s.amountOutMin,
                s.sqrtPriceLimitX96
            );

            return (amountOut, spent);
        }

        revert UNKNOWN_SWAP_KIND();
    }

    function _v3SwapExactInByPool(
        address pool,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOutMin,
        uint160 sqrtPriceLimitX96
    ) internal returns (uint256 amountOut, uint256 spent) {
        address t0 = IV3PoolLike(pool).token0();
        address t1 = IV3PoolLike(pool).token1();

        bool inIsT0 = (tokenIn == t0);
        bool inIsT1 = (tokenIn == t1);
        bool outIsT0 = (tokenOut == t0);
        bool outIsT1 = (tokenOut == t1);

        if (!((inIsT0 && outIsT1) || (inIsT1 && outIsT0))) revert TOKEN_NOT_IN_POOL();

        bool zeroForOne = inIsT0; // token0 -> token1

        uint160 limit = sqrtPriceLimitX96;
        if (limit == 0) {
            limit = zeroForOne ? (MIN_SQRT_RATIO + 1) : (MAX_SQRT_RATIO - 1);
        }

        // callback data: pool + tokenIn
        bytes memory data = abi.encode(pool, tokenIn);

        (int256 amount0, int256 amount1) = IV3PoolLike(pool).swap(
            address(this),
            zeroForOne,
            int256(amountIn), // exact input
            limit,
            data
        );

        // exact input: paid positive, received negative
        uint256 outAbs = uint256(-(zeroForOne ? amount1 : amount0));
        uint256 inAbs  = uint256( (zeroForOne ? amount0 : amount1) );

        if (outAbs < amountOutMin) revert SLIPPAGE();

        return (outAbs, inAbs);
    }

    // =========================================================
    // V3 callback: pay pool
    // =========================================================

    function uniswapV3SwapCallback(
        int256 amount0Delta,
        int256 amount1Delta,
        bytes calldata data
    ) external override {
        (address pool, address tokenIn) = abi.decode(data, (address, address));
        if (msg.sender != pool) revert NOT_FROM_POOL();

        if (amount0Delta > 0) {
            address t0 = IV3PoolLike(pool).token0();
            if (tokenIn != t0) revert TOKEN_NOT_IN_POOL();
            IERC20(t0).safeTransfer(pool, uint256(amount0Delta));
            return;
        }

        if (amount1Delta > 0) {
            address t1 = IV3PoolLike(pool).token1();
            if (tokenIn != t1) revert TOKEN_NOT_IN_POOL();
            IERC20(t1).safeTransfer(pool, uint256(amount1Delta));
            return;
        }

        // nothing owed
    }

    // =========================================================
    // Utils
    // =========================================================

    function _defaultPath(address tokenIn, address tokenOut)
    internal
    pure
    returns (address[] memory path)
    {
        path = new address[](2); // ✅ FIX
        path[0] = tokenIn;
        path[1] = tokenOut;
    }

    function _balanceOf(address token) internal view returns (uint256) {
        return IERC20(token).balanceOf(address(this));
    }

    function _ensureAllowance(address token, address spender, uint256 needed) internal {
        IERC20 erc = IERC20(token);
        uint256 allowance = erc.allowance(address(this), spender);
        if (allowance < needed) {
            // OZ v5: безопасный способ выставить allowance
            erc.forceApprove(spender, type(uint256).max);
        }
    }
}

