// SPDX-License-Identifier: MIT

//Deployed at: 0xC211C731f99F86922c4aC5b9625F6357B2b10010
//Owner: 0x90F0fE019Dd68e4bF4dacA998f00C758F7DF4ADE

pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * ArbVault (v1)
 * - Хранит ERC20 токены на контракте
 * - Хранит ETH (native coin Arbitrum) на контракте
 * - Owner может регистрировать токены для отображения (tracked list)
 * - Депозит токенов через transferFrom (нужен approve)
 * - Депозит ETH через receive() / depositETH()
 * - Вывод токенов/ETH owner'ом
 */
contract ArbVault is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ---- tracking ----
    address[] private _trackedTokens;
    mapping(address => bool) public isTrackedToken;

    // ---- events ----
    event TokenRegistered(address indexed token);
    event TokenDeposited(address indexed token, address indexed from, uint256 amount);
    event TokenWithdrawn(address indexed token, address indexed to, uint256 amount);

    event ETHDeposited(address indexed from, uint256 amount);
    event ETHWithdrawn(address indexed to, uint256 amount);

    constructor(address initialOwner) Ownable(initialOwner) {}

    // ======================================================================
    // ETH: RECEIVE / VIEW / DEPOSIT / WITHDRAW
    // ======================================================================

    /// @notice Принимаем ETH обычным переводом на адрес контракта
    receive() external payable {
        if (msg.value > 0) emit ETHDeposited(msg.sender, msg.value);
    }

    /// @notice (опционально) Явный депозит ETH вызовом функции
    function depositETH() external payable {
        require(msg.value > 0, "AMOUNT_ZERO");
        emit ETHDeposited(msg.sender, msg.value);
    }

    function ethBalance() external view returns (uint256) {
        return address(this).balance;
    }

    function withdrawETH(address payable to, uint256 amount)
    external
    onlyOwner
    nonReentrant
    {
        require(to != address(0), "TO_ZERO_ADDRESS");
        require(amount > 0, "AMOUNT_ZERO");
        require(address(this).balance >= amount, "INSUFFICIENT_ETH");

        (bool ok, ) = to.call{value: amount}("");
        require(ok, "ETH_TRANSFER_FAILED");

        emit ETHWithdrawn(to, amount);
    }

    function withdrawAllETH(address payable to)
    external
    onlyOwner
    nonReentrant
    returns (uint256 amount)
    {
        require(to != address(0), "TO_ZERO_ADDRESS");

        amount = address(this).balance;
        if (amount > 0) {
            (bool ok, ) = to.call{value: amount}("");
            require(ok, "ETH_TRANSFER_FAILED");

            emit ETHWithdrawn(to, amount);
        }
    }

    // ======================================================================
    // REGISTER / VIEW
    // ======================================================================

    function registerToken(address token) external onlyOwner {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        require(!isTrackedToken[token], "TOKEN_ALREADY_TRACKED");

        isTrackedToken[token] = true;
        _trackedTokens.push(token);

        emit TokenRegistered(token);
    }

    function trackedTokens() external view returns (address[] memory) {
        return _trackedTokens;
    }

    function trackedTokenBalances()
    external
    view
    returns (address[] memory tokens, uint256[] memory balances)
    {
        uint256 n = _trackedTokens.length;
        tokens = new address[](n);
        balances = new uint256[](n);

        for (uint256 i = 0; i < n; i++) {
            address t = _trackedTokens[i];
            tokens[i] = t;
            balances[i] = IERC20(t).balanceOf(address(this));
        }
    }

    function tokenBalance(address token) external view returns (uint256) {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        return IERC20(token).balanceOf(address(this));
    }

    // ======================================================================
    // DEPOSIT
    // ======================================================================

    function depositToken(address token, uint256 amount) external nonReentrant {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        require(amount > 0, "AMOUNT_ZERO");

        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        emit TokenDeposited(token, msg.sender, amount);
    }

    // ======================================================================
    // WITHDRAW (OWNER)
    // ======================================================================

    function withdrawToken(address token, address to, uint256 amount)
    external
    onlyOwner
    nonReentrant
    {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        require(to != address(0), "TO_ZERO_ADDRESS");
        require(amount > 0, "AMOUNT_ZERO");

        IERC20(token).safeTransfer(to, amount);
        emit TokenWithdrawn(token, to, amount);
    }

    function withdrawAllOfToken(address token, address to)
    external
    onlyOwner
    nonReentrant
    returns (uint256 amount)
    {
        require(token != address(0), "TOKEN_ZERO_ADDRESS");
        require(to != address(0), "TO_ZERO_ADDRESS");

        amount = IERC20(token).balanceOf(address(this));
        if (amount > 0) {
            IERC20(token).safeTransfer(to, amount);
            emit TokenWithdrawn(token, to, amount);
        }
    }

    function withdrawAllTrackedTokens(address to)
    external
    onlyOwner
    nonReentrant
    returns (address[] memory tokens, uint256[] memory amounts)
    {
        require(to != address(0), "TO_ZERO_ADDRESS");

        uint256 n = _trackedTokens.length;
        tokens = new address[](n);
        amounts = new uint256[](n);

        for (uint256 i = 0; i < n; i++) {
            address t = _trackedTokens[i];
            tokens[i] = t;

            uint256 bal = IERC20(t).balanceOf(address(this));
            amounts[i] = bal;

            if (bal > 0) {
                IERC20(t).safeTransfer(to, bal);
                emit TokenWithdrawn(t, to, bal);
            }
        }
    }
}

